pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/**
 * @title varaStreams Compliance and Verification Registry
 * @author Expert Solidity Engineer
 * @notice A smart contract system for managing compliance artifacts, their versions,
 * and attestations from auditors. It includes role-based access control, pausable
 * functionality, optional ERC20 staking for auditors, and meta-transaction support
 * for delegated submissions.
 */
contract varaStreams is AccessControl, Pausable, ReentrancyGuard, EIP712 {
    // --- Roles ---
    bytes32 public constant SUBMITTER_ROLE = keccak256("SUBMITTER_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    // --- Enums and Structs ---
    enum Status { ACTIVE, REVOKED, SUPERSEDED }

    struct Version {
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore; // 0-100
        uint256 verifiedAt;
        address submitter;
        Status status;
        uint256 gasUsed;
    }

    struct Attestation {
        address auditor;
        bool approved;
        bytes32 noteHash;
        uint256 attestedAt;
        uint8 confidenceLevel; // 1-5
    }

    struct SubmitterReputation {
        uint256 validSubmissions;
        uint256 revokedCount;
    }

    struct AuditorReputation {
        uint256 attestationCount;
        uint256 approvalCount;
    }

    struct SubmitVerificationRequest {
        bytes32 artifactHash;
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore;
        uint256 nonce;
    }

    // --- State Variables ---
    mapping(bytes32 => Version[]) private _versions;
    mapping(bytes32 => Attestation[]) private _attestations; // key is _getAttestationKey(...)
    mapping(bytes32 => mapping(address => uint256)) private _auditorAttestationIndex; // key is _getAttestationKey(...), value is index+1

    mapping(address => SubmitterReputation) public submitterReputation;
    mapping(address => AuditorReputation) public auditorReputation;

    // Staking
    IERC20 public stakingToken;
    uint256 public stakingRequirement;
    mapping(address => uint256) public stakes;

    // Meta-transactions
    mapping(address => uint256) public nonces;
    bytes32 private constant SUBMIT_VERIFICATION_TYPEHASH = keccak256(
        "SubmitVerificationRequest(bytes32 artifactHash,bytes32 resultsHash,string oscalCid,string profileId,uint256 complianceScore,uint256 nonce)"
    );

    // --- Events ---
    event VerificationSubmitted(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed submitter, bytes32 resultsHash);
    event VerificationRevoked(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed revoker, bytes32 reasonHash);
    event AttestationAdded(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed auditor, bool approved, uint8 confidenceLevel);
    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event Slashed(address indexed auditor, address indexed recipient, uint256 amount);
    event StakingTokenSet(address indexed token);
    event StakingRequirementSet(uint256 amount);

    // --- Constructor ---
    constructor() EIP712("varaStreams", "1") {
        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(PAUSER_ROLE, _msgSender());
        _grantRole(SUBMITTER_ROLE, _msgSender());
        _grantRole(AUDITOR_ROLE, _msgSender());
    }

    // --- Admin Functions ---
    function setStakingToken(address tokenAddress) public onlyRole(DEFAULT_ADMIN_ROLE) {
        stakingToken = IERC20(tokenAddress);
        emit StakingTokenSet(tokenAddress);
    }

    function setStakingRequirement(uint256 amount) public onlyRole(DEFAULT_ADMIN_ROLE) {
        stakingRequirement = amount;
        emit StakingRequirementSet(amount);
    }

    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // --- Core Functions ---
    function submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string calldata oscalCid,
        string calldata profileId,
        uint256 complianceScore
    ) public whenNotPaused onlyRole(SUBMITTER_ROLE) {
        _submitVerification(_msgSender(), artifactHash, resultsHash, oscalCid, profileId, complianceScore);
    }

    function revokeLatest(bytes32 artifactHash, bytes32 reasonHash) public whenNotPaused {
        (uint256 latestIndex, bool found) = _findLatestActiveVersionIndex(artifactHash);
        if (!found) {
            revert("No active version found");
        }

        Version storage latestVersion = _versions[artifactHash][latestIndex];

        if (_msgSender() != latestVersion.submitter && !hasRole(DEFAULT_ADMIN_ROLE, _msgSender())) {
            revert("Not authorized to revoke");
        }

        latestVersion.status = Status.REVOKED;

        SubmitterReputation storage reputation = submitterReputation[latestVersion.submitter];
        if (reputation.validSubmissions > 0) {
            reputation.validSubmissions--;
        }
        reputation.revokedCount++;

        emit VerificationRevoked(artifactHash, latestIndex, _msgSender(), reasonHash);
    }

    function attest(
        bytes32 artifactHash,
        uint256 versionIndex,
        bool approved,
        bytes32 noteHash,
        uint8 confidenceLevel
    ) public whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        if (stakingRequirement > 0) {
            if (address(stakingToken) == address(0)) revert("Staking token not set");
            if (stakes[_msgSender()] < stakingRequirement) revert("Insufficient stake");
        }

        if (versionIndex >= _versions[artifactHash].length) revert("Invalid version index");
        if (_versions[artifactHash][versionIndex].status != Status.ACTIVE) revert("Can only attest to active versions");
        if (confidenceLevel < 1 || confidenceLevel > 5) revert("Confidence level out of bounds (1-5)");

        bytes32 attestationKey = _getAttestationKey(artifactHash, versionIndex);
        uint256 attestationIndex = _auditorAttestationIndex[attestationKey][_msgSender()];
        AuditorReputation storage reputation = auditorReputation[_msgSender()];

        if (attestationIndex > 0) { // Update existing attestation
            Attestation storage existing = _attestations[attestationKey][attestationIndex - 1];
            if (existing.approved && !approved) {
                reputation.approvalCount--;
            } else if (!existing.approved && approved) {
                reputation.approvalCount++;
            }
            existing.approved = approved;
            existing.noteHash = noteHash;
            existing.confidenceLevel = confidenceLevel;
            existing.attestedAt = block.timestamp;
        } else { // Add new attestation
            _attestations[attestationKey].push(Attestation({
                auditor: _msgSender(),
                approved: approved,
                noteHash: noteHash,
                attestedAt: block.timestamp,
                confidenceLevel: confidenceLevel
            }));
            _auditorAttestationIndex[attestationKey][_msgSender()] = _attestations[attestationKey].length;
            reputation.attestationCount++;
            if (approved) {
                reputation.approvalCount++;
            }
        }

        emit AttestationAdded(artifactHash, versionIndex, _msgSender(), approved, confidenceLevel);
    }

    // --- Meta-Transaction Function ---
    function submitVerificationDelegated(SubmitVerificationRequest calldata req, bytes calldata signature) public whenNotPaused {
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(
            SUBMIT_VERIFICATION_TYPEHASH,
            req.artifactHash,
            req.resultsHash,
            keccak256(bytes(req.oscalCid)),
            keccak256(bytes(req.profileId)),
            req.complianceScore,
            req.nonce
        )));

        address signer = ECDSA.recover(digest, signature);
        if (signer == address(0)) revert("Invalid signature");
        if (!hasRole(SUBMITTER_ROLE, signer)) revert("Signer is not a submitter");
        if (nonces[signer] != req.nonce) revert("Invalid nonce");

        nonces[signer]++;

        _submitVerification(signer, req.artifactHash, req.resultsHash, req.oscalCid, req.profileId, req.complianceScore);
    }

    // --- Staking Functions ---
    function stake(uint256 amount) public whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        if (address(stakingToken) == address(0)) revert("Staking token not set");
        if (amount == 0) revert("Cannot stake zero");

        stakes[_msgSender()] += amount;
        if (!stakingToken.transferFrom(_msgSender(), address(this), amount)) {
            revert("ERC20 transferFrom failed");
        }

        emit Staked(_msgSender(), amount);
    }

    function unstake(uint256 amount) public whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        if (address(stakingToken) == address(0)) revert("Staking token not set");
        if (amount == 0) revert("Cannot unstake zero");

        uint256 currentStake = stakes[_msgSender()];
        if (amount > currentStake) revert("Insufficient staked amount");

        stakes[_msgSender()] = currentStake - amount;
        if (!stakingToken.transfer(_msgSender(), amount)) {
            revert("ERC20 transfer failed");
        }

        emit Unstaked(_msgSender(), amount);
    }

    function slash(address auditor, uint256 amount, address recipient) public whenNotPaused nonReentrant onlyRole(DEFAULT_ADMIN_ROLE) {
        if (address(stakingToken) == address(0)) revert("Staking token not set");
        if (amount == 0) revert("Cannot slash zero");
        if (recipient == address(0)) revert("Recipient cannot be zero address");

        uint256 auditorStake = stakes[auditor];
        if (amount > auditorStake) revert("Slash amount exceeds stake");

        stakes[auditor] = auditorStake - amount;
        if (!stakingToken.transfer(recipient, amount)) {
            revert("ERC20 transfer failed");
        }
        emit Slashed(auditor, recipient, amount);
    }

    // --- View Functions ---
    function getVersionCount(bytes32 artifactHash) public view returns (uint256) {
        return _versions[artifactHash].length;
    }

    function getVersion(bytes32 artifactHash, uint256 versionIndex) public view returns (Version memory) {
        if (versionIndex >= _versions[artifactHash].length) revert("Invalid version index");
        return _versions[artifactHash][versionIndex];
    }

    function getAttestations(bytes32 artifactHash, uint256 versionIndex) public view returns (Attestation[] memory) {
        bytes32 key = _getAttestationKey(artifactHash, versionIndex);
        return _attestations[key];
    }

    function getAuditorReputation(address auditor) public view returns (AuditorReputation memory, uint256 approvalRatio) {
        AuditorReputation memory reputation = auditorReputation[auditor];
        uint256 ratio = 0;
        if (reputation.attestationCount > 0) {
            ratio = (reputation.approvalCount * 10000) / reputation.attestationCount;
        }
        return (reputation, ratio);
    }

    // --- Internal Functions ---
    function _submitVerification(
        address submitter,
        bytes32 artifactHash,
        bytes32 resultsHash,
        string memory oscalCid,
        string memory profileId,
        uint256 complianceScore
    ) internal {
        uint256 gasStart = gasleft();
        if (complianceScore > 100) revert("Compliance score cannot exceed 100");

        (uint256 latestIndex, bool found) = _findLatestActiveVersionIndex(artifactHash);
        if (found) {
            _versions[artifactHash][latestIndex].status = Status.SUPERSEDED;
        }

        uint256 newVersionIndex = _versions[artifactHash].length;

        _versions[artifactHash].push(Version({
            resultsHash: resultsHash,
            oscalCid: oscalCid,
            profileId: profileId,
            complianceScore: complianceScore,
            verifiedAt: block.timestamp,
            submitter: submitter,
            status: Status.ACTIVE,
            gasUsed: gasStart - gasleft() // Approximate gas usage
        }));

        submitterReputation[submitter].validSubmissions++;

        emit VerificationSubmitted(artifactHash, newVersionIndex, submitter, resultsHash);
    }

    function _findLatestActiveVersionIndex(bytes32 artifactHash) internal view returns (uint256, bool) {
        uint256 count = _versions[artifactHash].length;
        for (uint256 i = count; i > 0; i--) {
            if (_versions[artifactHash][i - 1].status == Status.ACTIVE) {
                return (i - 1, true);
            }
        }
        return (0, false);
    }

    function _getAttestationKey(bytes32 artifactHash, uint256 versionIndex) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(artifactHash, versionIndex));
    }
}

